import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['knowledge_mgmt_flow'],
        name: 'Knowledge Management Flow',
        description: 'Trigger with reference column dot-walking',
    },
    wfa.trigger(trigger.application.knowledgeManagement, { $id: Now.ID['km_trigger'] }, {}),
    (params) => {
        // Test dot-walking on knowledge reference column
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_knowledge_details'] },
            {
                log_level: 'info',
                log_message: `Knowledge Article - Helpful: ${wfa.dataPill(params.trigger.knowledge.helpful_count, 'integer')}`,
            }
        )

        // Test accessing other trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_trigger_time'] },
            {
                log_level: 'info',
                log_message: `Trigger Time: ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}`,
            }
        )
    }
)
